function categoryRowToApp(row) {
  return { id: row.id, name: { ar: row.name_ar || "", en: row.name_en || "", fr: row.name_fr || "" } };
}
function categoryAppToRow(c) {
  return { id: c.id, name_ar: c.name.ar, name_en: c.name.en, name_fr: c.name.fr };
}
function slugifyCategoryId(s) {
  return s
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9؀-ۿ]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

// يولّد باركود مكوّن من ٦ أرقام فقط، مع تفادي التكرار مع الباركودات الموجودة
function generateBarcode(existingBarcodes = []) {
  let code;
  do {
    code = String(Math.floor(100000 + Math.random() * 900000));
  } while (existingBarcodes.includes(code));
  return code;
}

// يولّد رقم طلب فريد، مع تفادي التكرار مع أرقام الطلبات الموجودة
function generateOrderId(existingIds = []) {
  let id;
  do {
    id = "S-" + Date.now() + "-" + Math.floor(Math.random() * 1000);
  } while (existingIds.includes(id));
  return id;
}

const cartKey = (item) => item.id + "__" + (item.size || "");

// تحويل صفوف قاعدة البيانات (Supabase) من/إلى شكل الكائنات المستخدم بالواجهة

function productRowToApp(row) {
  return {
    id: row.id,
    cat: row.cat,
    color: row.color,
    name: { ar: row.name_ar || "", en: row.name_en || "", fr: row.name_fr || "" },
    mat: { ar: row.mat_ar || "", en: row.mat_en || "", fr: row.mat_fr || "" },
    desc: { ar: row.desc_ar || "", en: row.desc_en || "", fr: row.desc_fr || "" },
    price: Number(row.price) || 0,
    originalPrice: Number(row.original_price) || 0,
    cost: Number(row.cost) || 0,
    stock: row.stock ?? 0,
    sizes: row.sizes || [],
    images: row.images || [],
    countries: row.countries || [],
    rep: row.rep || "",
    barcode: row.barcode || "",
    hidden: !!row.hidden,
    views: row.views ?? 0,
    saleMethod: row.sale_method || "piece",
    weightGrams: row.weight_grams != null ? Number(row.weight_grams) : null,
    metalType: row.metal_type || null,
    goldKarat: row.gold_karat != null ? Number(row.gold_karat) : null,
    silverType: row.silver_type || null,
  };
}

function productAppToRow(p) {
  return {
    id: p.id,
    cat: p.cat,
    color: p.color,
    name_ar: p.name?.ar || "", name_en: p.name?.en || "", name_fr: p.name?.fr || "",
    mat_ar: p.mat?.ar || "", mat_en: p.mat?.en || "", mat_fr: p.mat?.fr || "",
    desc_ar: p.desc?.ar || "", desc_en: p.desc?.en || "", desc_fr: p.desc?.fr || "",
    price: p.price || 0,
    original_price: p.originalPrice || null,
    cost: p.cost || 0,
    stock: p.stock || 0,
    sizes: p.sizes || [],
    images: p.images || [],
    countries: p.countries || [],
    rep: p.rep || null,
    barcode: p.barcode || null,
    hidden: !!p.hidden,
    sale_method: p.saleMethod || "piece",
    weight_grams: p.saleMethod === "weight" ? p.weightGrams || null : null,
    metal_type: p.saleMethod === "weight" ? p.metalType || null : null,
    gold_karat: p.saleMethod === "weight" && p.metalType === "gold" ? p.goldKarat || null : null,
    silver_type: p.saleMethod === "weight" && p.metalType === "silver" ? p.silverType || null : null,
  };
}

function orderRowToApp(row, items) {
  return {
    id: row.id,
    date: row.order_date,
    country: row.country,
    payment: row.payment,
    customerName: row.customer_name || "",
    customerPhone: row.customer_phone || "",
    customerId: row.customer_id || null,
    status: row.status || "pending",
    items: items.map((it) => ({
      id: it.product_id,
      qty: it.qty,
      size: it.size,
      price: Number(it.price) || 0,
      cost: Number(it.cost) || 0,
      rep: it.rep || "",
    })),
  };
}

async function saveMetalPricesToDb(prices) {
  return supabase
    .from("metal_prices")
    .update({ gold_ounce: prices.goldOunce, silver_ounce: prices.silverOunce, updated_at: new Date().toISOString() })
    .eq("id", 1);
}

